// The storefront's "no photo" image: the Ammari mark on the --color-image-bg background,
// generated by packages/ui/assets/generate-storefront-placeholder.mjs into public/images/. Served
// as plain static files (never from object storage), so it renders even when storage itself is
// unreachable. The 2:3 files match every product image container's own aspect-[2/3] ratio, so
// swapping one in never shifts layout.

export const PRODUCT_PLACEHOLDER_SRC = {
  800: "/images/product-placeholder-800.webp",
  1600: "/images/product-placeholder-1600.webp",
} as const;

export type ProductPlaceholderSize = keyof typeof PRODUCT_PLACEHOLDER_SRC;

/** 1200x630 JPEG for Open Graph / JSON-LD, where crawlers expect a landscape JPEG/PNG. Relative
 * path: callers build the absolute URL against the site origin. */
export const PRODUCT_PLACEHOLDER_OG_PATH = "/images/product-placeholder-og.jpg";

export const PRODUCT_PLACEHOLDER_ALT = "Foto produk belum tersedia";
